INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_BELLEROPHON_HOMER_','ENT_BELLEROPHON','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','‘Proetus,'' said she, ‘kill Bellerophon or die, for he would have had converse with me against my will.'' The king was angered, but shrank from killing Bellerophon, so he sent him to Lycia with lying letters of introduction, written on a folded tablet, and containing much ill against the bearer.','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MELEAGER_HOMER_','ENT_MELEAGER','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','Meleager, then, stayed at home with Cleopatra, nursing the anger which he felt by reason of his mother''s curses. His mother, grieving for the death of her brother, prayed the gods, and beat the earth with her hands, calling upon Hades and on awful Proserpine; she went down upon her knees and her bosom was wet with tears as she prayed that they would kill her son-and Erinys that walks in darkness and knows no ruth heard her from Erebus.','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HECTOR_HOMER_','ENT_HECTOR','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','Hector and Ulysses measured the ground, and cast lots from a helmet of bronze to see which should take aim first. Meanwhile the two hosts lifted up their hands and prayed saying, "Father Jove, that rulest from Ida, most glorious in power, grant that he who first brought about this war between us may die, and enter the house of Hades, while we others remain at peace and abide by our oaths." Great Hector now turned his head aside while he shook the helmet, a','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_PROTESILAUS_HOMER_','ENT_PROTESILAUS','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','Of these brave Protesilaus had been captain while he was yet alive, but he was now lying under the earth. He had left a wife behind him in Phylace to tear her cheeks in sorrow, and his house was only half finished, for he was slain by a Dardanian warrior while leaping foremost of the Achaeans upon the soil of Troy.','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_BOREAS_HOMER_','ENT_BOREAS','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','haeans, but waves do not thunder on the shore more loudly when driven before the blast of Boreas, nor do the flames of a forest fire roar more fiercely when it is well alight upon the mountains, nor does the wind bellow with ruder music as it tears on through the tops of when it is blowing its hardest, than the terrible shout which the Trojans and Achaeans raised as they sprang upon one another.','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_DIOMEDES_HOMER_','ENT_DIOMEDES','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','In a second he was on the ground, whereupon the goddess mounted the car and placed herself by the side of Diomed. The oaken axle groaned aloud under the burden of the awful goddess and the hero; Pallas Minerva took the whip and reins, and drove straight at Mars. He was in the act of stripping huge Periphas, son of Ochesius and bravest of the Aetolians.','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GRR_ASPHODEL_HOMER_','ENT_GRR_ASPHODEL','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','lished cities, Cardamyle, Enope, and Hire, where there is grass; holy Pherae and the rich meadows of Anthea; Aepea also, and the vine-clad slopes of Pedasus, all near the sea, and on the borders of sandy Pylos. The men that dwell there are rich in cattle and sheep; they will honour him with gifts as though he were a god, and be obedient to his comfortable ordinances. All this will I do if he will now forgo his anger.','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_RHADAMANTHYS_HOMER_','ENT_RHADAMANTHYS','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','Then there was the daughter of Phoenix, who bore me Minos and Rhadamanthus: there was Semele, and Alcmena in Thebes by whom I begot my lion-hearted son Hercules, while Semele became mother to Bacchus the comforter of mankind. There was queen Ceres again, and lovely Leto, and yourself-but with none of these was I ever so much enamoured as I now am with you." Juno again answered him with a lying tale.','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ZEPHYRUS_HOMER_','ENT_ZEPHYRUS','SRC_HOMER_ILIAD_ODYSSEY','Homer, Iliad','Homer, Iliad','We two can fly as swiftly as Zephyrus who they say is fleetest of all winds; nevertheless it is your doom to fall by the hand of a man and of a god." When he had thus said the Erinyes stayed his speech, and Achilles answered him in great sadness, saying, "Why, O Xanthus, do you thus foretell my death? You need not do so, for I well know that I am to fall here, far from my dear father and mother; none the more, however, shall I stay my hand till I have give','Samuel Butler',1898,'https://www.gutenberg.org/ebooks/2199','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0133','primary-verbatim',NULL,true,'English prose translation located by name; locus is the Greek line-numbering — consult the original.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
